/*
 * Offline shell for بیمه ۲۴۷.
 *
 * Hand-written rather than generated by a plugin, because the one rule that matters here is a
 * judgement call no default strategy makes for you:
 *
 *   **Nothing from the API is ever cached.**
 *
 * This app quotes insurance. A price is valid for a few minutes, an OTP for two, a session
 * token until it rotates — serving any of them from a cache would show a customer a number
 * they can no longer buy at, or a policy list belonging to a session that has ended. The
 * network is the only acceptable source for all of it, and being offline must read as offline.
 *
 * What is cached is the *shell*: the HTML, the hashed JS/CSS bundles, the fonts and the brand
 * icons. Enough that opening the app on the underground shows the app saying it cannot reach
 * the server, instead of the browser's dinosaur.
 */

const VERSION = 'v1'
const SHELL_CACHE = `bimegold-shell-${VERSION}`
const ASSET_CACHE = `bimegold-assets-${VERSION}`

/** The document itself. Hashed bundles are picked up at runtime — their names change per build. */
const SHELL_URLS = ['/', '/brand/mark.svg', '/brand/icon-192.png', '/site.webmanifest']

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // `reload` so a stale HTTP cache cannot seed the shell with the previous deploy.
      .then((cache) => cache.addAll(SHELL_URLS.map((url) => new Request(url, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key.startsWith('bimegold-') && !key.endsWith(VERSION))
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  )
})

/** Same-origin build output: immutable, because Vite puts a content hash in every filename. */
const isHashedAsset = (url) =>
  url.origin === self.location.origin && url.pathname.startsWith('/assets/')

const isShellAsset = (url) =>
  url.origin === self.location.origin &&
  (url.pathname.startsWith('/brand/') || url.pathname === '/site.webmanifest')

self.addEventListener('fetch', (event) => {
  const { request } = event
  if (request.method !== 'GET') return

  const url = new URL(request.url)

  /*
   * Anything that is not a same-origin static asset is left entirely alone — no cache read, no
   * cache write, not even a pass-through handler. That covers the API on its own origin, the
   * mock gateway, and any third party. `fetch` failing there is the correct behaviour: the UI
   * already turns a failed request into «ارتباط با سرور برقرار نشد».
   */
  if (url.origin !== self.location.origin) return
  if (url.pathname.startsWith('/api/')) return

  // Navigations: network first, so a deploy is picked up on the next load; cached shell when
  // the network is gone, so the app still boots and can say so in its own words.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(() =>
        caches.match('/', { cacheName: SHELL_CACHE }).then(
          (cached) =>
            cached ??
            new Response('<!doctype html><meta charset="utf-8"><title>آفلاین</title>', {
              status: 503,
              headers: { 'Content-Type': 'text/html; charset=utf-8' },
            }),
        ),
      ),
    )
    return
  }

  if (isHashedAsset(url) || isShellAsset(url)) {
    event.respondWith(
      caches.match(request).then(
        (cached) =>
          cached ??
          fetch(request).then((response) => {
            // Only a complete, successful response is worth keeping; a 404 cached is a 404 forever.
            if (response.ok && response.status === 200) {
              const copy = response.clone()
              void caches.open(ASSET_CACHE).then((cache) => cache.put(request, copy))
            }
            return response
          }),
      ),
    )
  }
})
